{
  "root": "main_stack",
  "state": {
    "itinerary_rows": [
      {
        "day": "November 15, 2024",
        "timeRange": "09:00 - 10:30",
        "activity": "Keynote: Dr. Aris",
        "location": "Hall A"
      },
      {
        "day": "November 15, 2024",
        "timeRange": "11:30 - 13:00",
        "activity": "AI Workshop",
        "location": "Room 202"
      },
      {
        "day": "November 15, 2024",
        "timeRange": "13:00 - 14:30",
        "activity": "Lunch Break",
        "location": "Dining Hall"
      },
      {
        "day": "November 15, 2024",
        "timeRange": "16:00 - 17:30",
        "activity": "Networking Mixer",
        "location": "Garden"
      },
      {
        "day": "November 16, 2024",
        "timeRange": "10:00 - 11:30",
        "activity": "Blockchain Panel",
        "location": "Hall B"
      },
      {
        "day": "November 16, 2024",
        "timeRange": "14:00 - 15:30",
        "activity": "Cybersecurity Deep Dive",
        "location": "Room 105"
      },
      {
        "day": "November 16, 2024",
        "timeRange": "19:00 - 20:30",
        "activity": "Gala Dinner",
        "location": "Main Ballroom"
      },
      {
        "day": "November 17, 2024",
        "timeRange": "09:30 - 11:00",
        "activity": "Startup Pitch Competition",
        "location": "Hall A"
      },
      {
        "day": "November 17, 2024",
        "timeRange": "15:00 - 16:30",
        "activity": "Closing Ceremony",
        "location": "Hall A"
      }
    ]
  },
  "elements": {
    "main_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "md"
      },
      "children": [
        "title",
        "description",
        "itinerary_section_stack",
        "quick_actions_section_stack",
        "sources_section_stack"
      ]
    },
    "title": {
      "type": "Text",
      "props": {
        "text": "Global Tech Innovation Summit: Berlin 2024",
        "variant": "h1"
      },
      "children": []
    },
    "description": {
      "type": "Text",
      "props": {
        "text": "This three-day summit in Berlin brings together industry leaders for deep dives into AI, Blockchain, and Cybersecurity, concluding with a startup pitch competition.",
        "variant": "body"
      },
      "children": []
    },
    "itinerary_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "itinerary_heading_with_icon",
        "itinerary_image",
        "itinerary_table"
      ]
    },
    "itinerary_heading_with_icon": {
      "type": "Stack",
      "props": {
        "direction": "horizontal",
        "gap": "sm",
        "align": "center"
      },
      "children": [
        "itinerary_icon",
        "itinerary_heading"
      ]
    },
    "itinerary_icon": {
      "type": "Icon",
      "props": {
        "name": "https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/icons/calendar.svg"
      },
      "children": []
    },
    "itinerary_heading": {
      "type": "Text",
      "props": {
        "text": "3-Day Innovation Itinerary",
        "variant": "h2"
      },
      "children": []
    },
    "itinerary_image": {
      "type": "Image",
      "props": {
        "url": "https://upload.wikimedia.org/wikipedia/commons/thumb/8/83/Brandenburger_Tor_abends.jpg/1200px-Brandenburger_Tor_abends.jpg",
        "fit": "cover"
      },
      "children": []
    },
    "itinerary_table": {
      "type": "Table",
      "props": {
        "statePath": "/itinerary_rows",
        "columns": [
          {
            "key": "day",
            "label": "Day"
          },
          {
            "key": "timeRange",
            "label": "Time"
          },
          {
            "key": "activity",
            "label": "Activity"
          },
          {
            "key": "location",
            "label": "Location"
          }
        ],
        "domain": "schedule",
        "preferredPresentation": "cards",
        "primaryColumn": "day",
        "highlightColumns": [
          "activity"
        ]
      },
      "children": []
    },
    "quick_actions_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "quick_actions_heading",
        "speaker_bios_button",
        "directions_button"
      ]
    },
    "quick_actions_heading": {
      "type": "Text",
      "props": {
        "text": "Quick Actions",
        "variant": "h2"
      },
      "children": []
    },
    "speaker_bios_button": {
      "type": "Button",
      "props": {
        "label": "Speaker Bios"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://techinnovation-berlin.de/speakers"
          }
        }
      },
      "children": []
    },
    "directions_button": {
      "type": "Button",
      "props": {
        "label": "Directions"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://techinnovation-berlin.de/location"
          }
        }
      },
      "children": []
    },
    "sources_section_stack": {
      "type": "Stack",
      "props": {
        "direction": "vertical",
        "gap": "sm"
      },
      "children": [
        "sources_heading",
        "official_schedule_button",
        "berlin_events_button"
      ]
    },
    "sources_heading": {
      "type": "Text",
      "props": {
        "text": "Sources",
        "variant": "h2"
      },
      "children": []
    },
    "official_schedule_button": {
      "type": "Button",
      "props": {
        "label": "Official Summit Schedule"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://techinnovation-berlin.de/agenda"
          }
        }
      },
      "children": []
    },
    "berlin_events_button": {
      "type": "Button",
      "props": {
        "label": "Berlin Business Events"
      },
      "on": {
        "press": {
          "action": "openUrl",
          "params": {
            "url": "https://www.berlin-partner.de/en/"
          }
        }
      },
      "children": []
    }
  }
}
